const API='http://localhost:8000/api';
const pages={overview:{title:'Overview',html:()=>`<div class="grid"><div class="card"><div class="muted">Total Requests</div><div class="metric">4,821</div><div class="positive">↑ 18.4% this month</div></div><div class="card"><div class="muted">Tokens Processed</div><div class="metric">184.3K</div><div class="positive">↑ 12.8% this month</div></div><div class="card"><div class="muted">Active Users</div><div class="metric">1,284</div><div class="positive">↑ 7.2% this month</div></div><div class="card"><div class="muted">AI Spend</div><div class="metric">$37.42</div><div class="positive">↓ 4.1% this month</div></div></div><div class="split section"><div class="card"><h2>Usage Analytics</h2><div class="muted">Requests across the last 12 months</div><div class="chart">${[42,65,52,76,58,83,70,92,64,78,88,96].map(x=>`<div class="bar" style="height:${x}%"></div>`).join('')}</div></div><div class="card"><h2>Recent Activity</h2><div class="list"><div class="row"><span>Document indexed</span><span class="pill">2m</span></div><div class="row"><span>Agent deployed</span><span class="pill">18m</span></div><div class="row"><span>API key created</span><span class="pill">42m</span></div><div class="row"><span>New workspace member</span><span class="pill">1h</span></div></div></div></div>`},chat:{title:'AI Chat',html:()=>`<div class="chatbox"><div class="messages" id="messages"><div class="bubble">Hello! I'm NexaAI. Ask me anything or describe a task.</div></div><div class="composer"><input id="chatInput" placeholder="Message NexaAI..."><button class="btn" id="send">Send</button></div></div>`},documents:{title:'Documents',html:()=>`<div class="card"><h2>Document Intelligence</h2><p class="muted">Upload and index knowledge for RAG-powered answers.</p><input class="input" id="docName" placeholder="Document name"><button class="btn" id="addDoc">Index document</button><div id="docList" class="list section"></div></div>`},agents:{title:'Agents',html:()=>`<div class="card"><h2>AI Agents</h2><p class="muted">Create task-oriented autonomous workflows.</p><input class="input" id="agentName" placeholder="Agent name"><button class="btn" id="addAgent">Deploy agent</button><div id="agentList" class="list section"></div></div>`},prompts:{title:'Prompts',html:()=>`<div class="grid"><div class="card"><h2>Prompt Library</h2><p class="muted">Reusable production prompts for teams.</p><button class="btn">Create prompt</button></div><div class="card"><h2>Evaluation</h2><p class="muted">Compare prompt versions with quality metrics.</p><button class="btn">Run evaluation</button></div></div>`},analytics:{title:'Analytics',html:()=>`<div class="grid"><div class="card"><div class="muted">P95 Latency</div><div class="metric">1.82s</div></div><div class="card"><div class="muted">Success Rate</div><div class="metric">99.2%</div></div><div class="card"><div class="muted">Avg Tokens</div><div class="metric">38.2</div></div><div class="card"><div class="muted">Cost / Request</div><div class="metric">$0.007</div></div></div>`},api:{title:'API Keys',html:()=>`<div class="card"><h2>Developer API</h2><p class="muted">Manage keys used by your applications.</p><button class="btn" id="newKey">Create API key</button><div id="keyList" class="list section"></div></div>`},billing:{title:'Billing',html:()=>`<div class="grid"><div class="card"><div class="muted">Current Plan</div><div class="metric">Pro</div><p>Usage-based AI platform access</p><button class="btn">Manage plan</button></div><div class="card"><div class="muted">Current period</div><div class="metric">$37.42</div><p class="muted">Next invoice: Sep 1, 2026</p></div></div>`}};
function render(p){document.querySelector('#title').textContent=pages[p].title;document.querySelector('#content').innerHTML=pages[p].html();if(p==='chat')setupChat();if(p==='documents')loadDocs();if(p==='agents')loadAgents();if(p==='api')loadKeys()}
document.querySelectorAll('.nav[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.page)});render('overview');
async function setupChat(){const input=document.querySelector('#chatInput');document.querySelector('#send').onclick=async()=>{let m=input.value.trim();if(!m)return;let box=document.querySelector('#messages');box.innerHTML+=`<div class="bubble user">${m.replaceAll('<','&lt;')}</div>`;input.value='';try{let r=await fetch(API+'/echo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:m})});let d=await r.json();box.innerHTML+=`<div class="bubble">${d.reply}</div>`}catch(e){box.innerHTML+=`<div class="bubble">Backend is offline. Start Flask on port 8000.</div>`}box.scrollTop=box.scrollHeight}}
async function loadDocs(){let el=document.querySelector('#docList');el.innerHTML='<div class="muted">No documents indexed.</div>';document.querySelector('#addDoc').onclick=async()=>{let name=document.querySelector('#docName').value||'Untitled document';try{await fetch(API+'/documents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})})}catch(e){}el.innerHTML+=`<div class="row"><span>${name}</span><span class="pill">indexed</span></div>`}}
async function loadAgents(){let el=document.querySelector('#agentList');el.innerHTML='<div class="muted">No agents deployed.</div>';document.querySelector('#addAgent').onclick=async()=>{let name=document.querySelector('#agentName').value||'Untitled Agent';try{await fetch(API+'/agents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})})}catch(e){}el.innerHTML+=`<div class="row"><span>${name}</span><span class="pill">active</span></div>`}}
async function loadKeys(){let el=document.querySelector('#keyList');el.innerHTML='<div class="muted">No API keys created.</div>';document.querySelector('#newKey').onclick=async()=>{try{await fetch(API+'/keys',{method:'POST'})}catch(e){}el.innerHTML+=`<div class="row"><span>nx_live_••••••••</span><span class="pill">active</span></div>`}}

